// AUTO-GENERATED pipeline: walk the nexscope-ecommerce-skills pack and emit
// public/skills-data.js (window.NEXSCOPE_SKILLS + window.NEXSCOPE_META).
// Re-run after editing the source pack.
import { readFileSync, writeFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const SRC = "C:/Users/21907/.workbuddy/tmp/nexscope_src/nexscope-ecommerce-skills-main";
const OUT = "C:/Users/21907/Documents/codex电商/public/skills-data.js";

// Friendly Chinese/English labels for each platform/category token.
const LABELS = {
  amazon: "Amazon",
  tiktok: "TikTok Shop",
  patent: "专利检索",
  ozon: "Ozon",
  walmart: "Walmart",
  "1688": "1688",
  etsy: "Etsy",
  google: "Google",
  ruiguan: "瑞观数据",
  temu: "Temu",
  mercado: "MercadoLibre",
  multimodal: "多模态",
  shopee: "Shopee",
  shopify: "Shopify",
  product: "产品工具",
  zhihuiya: "智慧芽",
  ebay: "eBay",
  geo: "地理区域",
  maidalv: "麦达律",
  reverse: "逆向反推",
  text: "文本工具",
  utility: "通用工具",
  web: "Web 工具",
};

// Words that should render uppercase in display titles.
const ACRONYMS = new Set([
  'api', 'id', 'url', 'uri', 'seo', 'cpc', 'roi', 'asin', 'sku', 'ctr', 'gmv',
  'ai', 'ui', 'ux', 'html', 'css', 'json', 'xml', 'csv', 'pdf', 'sms', 'erp',
  'crm', 'sku', 'qps', 'ip', 'uv', 'pv',
]);

function readJSON(p) {
  try { return JSON.parse(readFileSync(p, 'utf8')); } catch { return null; }
}

if (!existsSync(SRC)) {
  console.error("Source pack not found at", SRC);
  process.exit(1);
}

const dirs = readdirSync(SRC).filter(
  (d) => statSync(join(SRC, d)).isDirectory() && d.startsWith('ecommerce-')
);

const skills = [];
for (const d of dirs) {
  const base = join(SRC, d);
  const manifest = readJSON(join(base, 'manifest.json')) || {};

  let fmName = '', fmDesc = '', fmVersion = '';
  try {
    const md = readFileSync(join(base, 'SKILL.md'), 'utf8');
    const fm = md.match(/^---\s*([\s\S]*?)\n---/);
    if (fm) {
      const block = fm[1];
      const nameM = block.match(/name:\s*(.+)/);
      if (nameM) fmName = nameM[1].trim().replace(/^["']|["']$/g, '');
      const descM = block.match(/description:\s*(.+)/);
      if (descM) fmDesc = descM[1].trim().replace(/^["']|["']$/g, '');
      const verM = block.match(/version:\s*(.+)/);
      if (verM) fmVersion = verM[1].trim().replace(/^["']|["']$/g, '');
    }
  } catch { /* no SKILL.md frontmatter */ }

  const name = manifest.name || fmName || d;
  const description = manifest.description || fmDesc || '';
  const triggers = Array.isArray(manifest.triggers) ? manifest.triggers : [];
  const version = manifest.version || fmVersion || '';
  const category = d.split('-')[1] || 'misc';
  const files = Array.isArray(manifest.files) ? manifest.files : [];

  // Human-friendly display title: drop the "ecommerce-" prefix, split on hyphens,
  // capitalize words longer than 2 chars, and force known acronyms to uppercase
  // (so "amazon-ads-api-access" -> "Amazon Ads API Access", not "... Api ...").
  const title = d.replace(/^ecommerce-/, '').split('-')
    .map((w) => {
      if (ACRONYMS.has(w.toLowerCase())) return w.toUpperCase();
      return w.length > 2 ? w[0].toUpperCase() + w.slice(1) : w;
    })
    .join(' ');

  skills.push({
    id: d,
    name,
    title,
    description,
    triggers,
    category,
    categoryLabel: LABELS[category] || category,
    version,
    files,
    fileCount: files.length,
  });
}

skills.sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name));

const categories = [...new Set(skills.map((s) => s.category))]
  .map((c) => ({ key: c, label: LABELS[c] || c, count: skills.filter((s) => s.category === c).length }))
  .sort((a, b) => b.count - a.count);

const out =
  `// AUTO-GENERATED by scripts/gen-skills-data.mjs — do not edit by hand.\n` +
  `window.NEXSCOPE_SKILLS = ${JSON.stringify(skills)};\n` +
  `window.NEXSCOPE_META = ${JSON.stringify({ total: skills.length, categories })};\n`;

writeFileSync(OUT, out);
console.log(`Wrote ${skills.length} skills across ${categories.length} categories -> ${OUT}`);
console.log('Top categories:', categories.slice(0, 8).map((c) => `${c.label}(${c.count})`).join(', '));
